	case 16: return E.Cranklength.IsSet();
	case 17: return E.Joint.IsSet();
	case 18: return E.Jointinparent.IsSet();
	case 19: return E.Tendon.IsSet();
	case 20: return E.Slidersite.IsSet();
	case 21: return E.Cranksite.IsSet();
